<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class ComparisonRun extends Model{protected $fillable=['baseline_survey_id','followup_survey_id','created_by','status','is_comparable','compatibility_checks','baseline_metrics','followup_metrics','changes','limitations','calculation_version','calculated_at'];protected function casts():array{return ['is_comparable'=>'boolean','compatibility_checks'=>'array','baseline_metrics'=>'array','followup_metrics'=>'array','changes'=>'array','limitations'=>'array','calculated_at'=>'datetime'];}public function baseline(){return $this->belongsTo(Survey::class,'baseline_survey_id');}public function followup(){return $this->belongsTo(Survey::class,'followup_survey_id');}public function creator(){return $this->belongsTo(User::class,'created_by');}}
